#[path = "solution.rs"]
mod solution;

use solution::{record_digest, Transfer, TransferLog};

fn independent_digest(t: &Transfer, sequence: u64, previous: u64) -> u64 {
    let mut bytes = Vec::new();
    bytes.extend_from_slice(t.from.as_bytes());
    bytes.push(0);
    bytes.extend_from_slice(t.to.as_bytes());
    bytes.push(0);
    bytes.extend_from_slice(&t.units.to_le_bytes());
    bytes.extend_from_slice(&sequence.to_le_bytes());
    bytes.extend_from_slice(&previous.to_le_bytes());
    bytes.into_iter().fold(14695981039346656037u64, |hash, byte| {
        (hash ^ u64::from(byte)).wrapping_mul(1099511628211)
    })
}

fn transfer(from: &str, to: &str, units: u64) -> Transfer {
    Transfer { from: from.to_string(), to: to.to_string(), units }
}

#[test]
fn digest_follows_exact_byte_recipe_and_is_deterministic() {
    let t = transfer("alice", "bob", u64::MAX);
    let expected = independent_digest(&t, 7, 99);
    assert_eq!(record_digest(&t, 7, 99), expected);
    assert_eq!(record_digest(&t, 7, 99), expected);
    assert_ne!(record_digest(&t, 8, 99), expected);
}

#[test]
fn appends_a_linked_chain_and_returns_digests() {
    let mut log = TransferLog::new();
    assert!(log.is_valid());
    let first_transfer = transfer("a", "b", 0);
    let first = log.append(first_transfer.clone()).unwrap();
    assert_eq!(first, independent_digest(&first_transfer, 0, 0));
    let second_transfer = transfer("b", "c", u64::MAX);
    let second = log.append(second_transfer.clone()).unwrap();
    assert_eq!(second, independent_digest(&second_transfer, 1, first));
    assert_eq!(log.records[0].sequence, 0);
    assert_eq!(log.records[0].previous_digest, 0);
    assert_eq!(log.records[1].sequence, 1);
    assert_eq!(log.records[1].previous_digest, first);
    assert!(log.is_valid());
}

#[test]
fn empty_parties_are_rejected_without_mutation() {
    let mut log = TransferLog::new();
    log.append(transfer("a", "b", 1)).unwrap();
    for bad in [transfer("", "b", 1), transfer("a", "", 1), transfer("", "", 1)] {
        let before = log.clone();
        assert!(log.append(bad).is_err());
        assert_eq!(log, before);
    }
}

#[test]
fn validation_detects_every_publicly_tamperable_component() {
    let mut original = TransferLog::new();
    original.append(transfer("a", "b", 10)).unwrap();
    original.append(transfer("b", "c", 20)).unwrap();

    let mut cases = Vec::new();
    let mut x = original.clone(); x.records[0].transfer.from.push('x'); cases.push(x);
    let mut x = original.clone(); x.records[0].transfer.to.push('x'); cases.push(x);
    let mut x = original.clone(); x.records[0].transfer.units += 1; cases.push(x);
    let mut x = original.clone(); x.records[1].sequence = 0; cases.push(x);
    let mut x = original.clone(); x.records[1].previous_digest ^= 1; cases.push(x);
    let mut x = original.clone(); x.records[1].digest ^= 1; cases.push(x);
    for log in cases {
        let before = log.clone();
        assert!(!log.is_valid());
        assert_eq!(log, before);
    }
}

